    public val easingSoft: CubicBezierEasing = CubicBezierEasing(0.23f, 1f, 0.32f, 1f)
    public val travelPop: Dp = 4.dp
    public val travelRise: Dp = 6.dp
    public val travelDialog: Dp = 8.dp
    public val travelReduced: Dp = 0.dp
}

