/** Material3 typography built from the type roles (each role names its slot). */
public val EquipeTypography: Typography = Typography(
    displaySmall = EquipeType.display.toTextStyle(),
    headlineMedium = EquipeType.headline.toTextStyle(),
    titleLarge = EquipeType.title.toTextStyle(),
    bodyLarge = EquipeType.body.toTextStyle(),
    bodyMedium = EquipeType.ui.toTextStyle(),
    labelLarge = EquipeType.label.toTextStyle(),
    bodySmall = EquipeType.small.toTextStyle(),
    labelMedium = EquipeType.meta.toTextStyle()
)

/** Starting point for MaterialTheme: keeps the current Theme.kt mapping (surface = bg, surfaceVariant = card), now fed by tokens. */
public fun equipeMaterialColors(dark: Boolean): androidx.compose.material3.ColorScheme = (if (dark) EquipeColors.Dark else EquipeColors.Light).let { c ->
    if (dark) darkColorScheme(
        primary = c.colorAction,
        onPrimary = c.colorOnAction,
        background = c.colorBg,
        onBackground = c.colorText,
        surface = c.colorBg,
        onSurface = c.colorText,
        surfaceVariant = c.colorSurface,
        onSurfaceVariant = c.colorMuted,
        surfaceContainer = c.colorSurface,
        surfaceContainerHigh = c.colorRaised,
        secondaryContainer = c.colorSunken,
        onSecondaryContainer = c.colorText,
        outline = c.colorLine,
        outlineVariant = c.colorLine,
        error = c.colorErr,
        onError = c.colorOnErr
    ) else lightColorScheme(
        primary = c.colorAction,
        onPrimary = c.colorOnAction,
        background = c.colorBg,
        onBackground = c.colorText,
        surface = c.colorBg,
        onSurface = c.colorText,
        surfaceVariant = c.colorSurface,
        onSurfaceVariant = c.colorMuted,
        surfaceContainer = c.colorSurface,
        surfaceContainerHigh = c.colorRaised,
        secondaryContainer = c.colorSunken,
        onSecondaryContainer = c.colorText,
        outline = c.colorLine,
        outlineVariant = c.colorLine,
        error = c.colorErr,
        onError = c.colorOnErr
    )
}
